import javax.swing.*; import java.awt.event.*; public class SimpleMenuExample { public static void main(String[] args) { JFrame frame = new JFrame("Simple Menu"); frame.setSize(400, 300); frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE); JMenuBar mb = new JMenuBar(); JMenu menu = new JMenu("File"); JMenuItem open = new JMenuItem("Open"); JMenuItem exit = new JMenuItem("Exit"); exit.addActionListener(e -> System.exit(0)); open.addActionListener(e -> JOptionPane.showMessageDialog(frame, "Open Clicked!")); menu.add(open); menu.add(exit); mb.add(menu); frame.setJMenuBar(mb); frame.setVisible(true); } }
